INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7731952, 1274094, 30861, '<td valign="top">You ain''t that old, Wiley.</td>', 'You ain''t that old, Wiley.', '2022-11-02 11:41:45.000000', NULL, 1),
(7731956, 1274038, 117474, '<td valign="top">very cool.</td>', 'very cool.', '2022-11-02 13:34:21.000000', NULL, 1),
(7731962, 1274050, 117474, '<td valign="top">i''m a bit of an insomniac. this speaks loudly to me, unfortunately. i think the simplicity of the image is a great choice. particularly because (and i hope you don''t take this as a criticism because it''s not!) insomnia is usually super boring. sometimes, i can despair of insomnia, so i can''t resist thinking about how i would capture that in an image like this. possibly i would take it at a low dramatic low angle with an ultra wide lens and exaggerate the lens distortion in pp. but like i said, this is close to perfect for me.</td>', 'i''m a bit of an insomniac. this speaks loudly to me, unfortunately. i think the simplicity of the image is a great choice. particularly because (and i hope you don''t take this as a criticism because it''s not!) insomnia is usually super boring. sometimes, i can despair of insomnia, so i can''t resist thinking about how i would capture that in an image like this. possibly i would take it at a low dramatic low angle with an ultra wide lens and exaggerate the lens distortion in pp. but like i said, this is close to perfect for me.', '2022-11-02 13:43:58.000000', NULL, 1),
(7731963, 1274088, 117474, '<td valign="top">i''m curious how you got this effect. i like the abstract nature of it a lot!</td>', 'i''m curious how you got this effect. i like the abstract nature of it a lot!', '2022-11-02 13:44:31.000000', NULL, 1),
(7731964, 1274093, 117474, '<td valign="top">this is perfect! i love everything about it. it''s lighthearted and fun, a bit crazy and the toning is gorgeous.</td>', 'this is perfect! i love everything about it. it''s lighthearted and fun, a bit crazy and the toning is gorgeous.', '2022-11-02 13:45:15.000000', NULL, 1),
(7731965, 1274039, 117474, '<td valign="top">made me laugh! :-D</td>', 'made me laugh! :-D', '2022-11-02 13:45:28.000000', NULL, 1),
(7731966, 1274095, 117474, '<td valign="top">it''s very bright for late night photo for me :-) i feel like it would ruin my feeble attempts at sleep.</td>', 'it''s very bright for late night photo for me :-) i feel like it would ruin my feeble attempts at sleep.', '2022-11-02 13:46:05.000000', NULL, 1),
